"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    # Build the set of all nodes (explicit keys + implicit leaves from dependency lists)
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    if not all_nodes:
        return []

    # Normalize the graph: collapse duplicate dependencies and ensure all nodes are present
    graph_normalized = {}
    dependents = {}  # node -> list of nodes that depend on it
    in_degree = {}

    for node in all_nodes:
        if node in graph:
            # Collapse duplicates by converting to set and back to list
            graph_normalized[node] = list(set(graph[node]))
        else:
            # Implicit leaf with no dependencies
            graph_normalized[node] = []

        in_degree[node] = len(graph_normalized[node])
        dependents[node] = []

    # Build the reverse dependency mapping: for each node, which nodes depend on it
    for node in all_nodes:
        for dep in graph_normalized[node]:
            dependents[dep].append(node)

    # Kahn's algorithm for topological sort with lexicographic tie-breaking
    result = []

    while len(result) < len(all_nodes):
        # Find all nodes that are ready (all dependencies satisfied)
        ready = [node for node in all_nodes if in_degree[node] == 0 and node not in result]

        if not ready:
            # No ready nodes but not all nodes processed = cycle exists
            cycle = _find_cycle(graph_normalized, all_nodes)
            raise CycleError(cycle)

        # Pick the lexicographically smallest ready node
        ready.sort()
        next_node = ready[0]
        result.append(next_node)

        # Decrease in-degree of all nodes that depend on the node we just processed
        for dependent in dependents[next_node]:
            in_degree[dependent] -= 1

    return result


def _find_cycle(graph: dict[str, list[str]], all_nodes: set[str]) -> list[str]:
    """Find a cycle in the graph using DFS, return the shortest/best one."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in all_nodes}
    cycles = []

    def dfs(node: str, path: list[str]) -> None:
        color[node] = GRAY
        new_path = path + [node]

        for neighbor in graph[node]:
            if color[neighbor] == GRAY:
                # Back edge found - cycle detected
                cycle_start_idx = new_path.index(neighbor)
                cycle = new_path[cycle_start_idx:]
                cycles.append(cycle)
            elif color[neighbor] == WHITE:
                dfs(neighbor, new_path)

        color[node] = BLACK

    # Run DFS from each unvisited node
    for start in all_nodes:
        if color[start] == WHITE:
            dfs(start, [])

    # Sort cycles by: length (shortest first), then by normalized form (lexicographically smallest)
    def normalize_cycle(cycle: list[str]) -> tuple[str, ...]:
        """Rotate cycle to start at its lexicographically smallest element."""
        if not cycle:
            return ()
        min_idx = min(range(len(cycle)), key=lambda i: cycle[i])
        rotated = cycle[min_idx:] + cycle[:min_idx]
        return tuple(rotated)

    cycles.sort(key=lambda c: (len(c), normalize_cycle(c)))

    # Return the best cycle, rotated to start with its lexicographically smallest element
    if not cycles:
        return []
    best_cycle = cycles[0]
    normalized = normalize_cycle(best_cycle)
    return list(normalized)
